// Mantener la pantalla encendida (Wake Lock API o video de respaldo).
// Script clásico (no módulo): comparte el ámbito global con el resto de la app.

// La Screen Wake Lock API sólo funciona en "contexto seguro" (https o
// localhost). Al abrir este HTML directo desde el celular, Chrome lo
// carga como content://media/..., que NO es contexto seguro: la API
// existe pero request() siempre rechaza. Antes ese error se tragaba
// en silencio (catch vacío) y el botón se marcaba "activo" sin hacer
// nada. Por eso hay un fallback que sí funciona ahí: un video mudo de
// 1 frame en loop (misma técnica que usa NoSleep.js), que no depende
// de contexto seguro.
let wakeLock = null;

let wakeLockEnabled = false;

let wakeLockMode = null; // 'api' | 'video' | null
let noSleepVideoEl = null;

const NOSLEEP_VIDEO_SRC = 'data:video/mp4;base64,';

function getNoSleepVideoEl() {
    if (noSleepVideoEl) return noSleepVideoEl;
    const v = document.createElement('video');
    v.setAttribute('playsinline', '');
    v.setAttribute('webkit-playsinline', '');
    v.muted = true;
    v.loop = true;
    v.setAttribute('aria-hidden', 'true');
    v.style.cssText = 'position:fixed;top:0;left:0;width:1px;height:1px;opacity:0.01;pointer-events:none;';
    const source = document.createElement('source');
    source.src = NOSLEEP_VIDEO_SRC;
    source.type = 'video/mp4';
    v.appendChild(source);
    document.body.appendChild(v);
    noSleepVideoEl = v;
    return v;
}

async function requestWakeLock() {
    if ('wakeLock' in navigator && window.isSecureContext) {
        try {
            wakeLock = await navigator.wakeLock.request('screen');
            wakeLock.addEventListener('release', () => { wakeLock = null; });
            wakeLockMode = 'api';
            return true;
        } catch (e) {
            wakeLock = null;
        }
    }
    // Fallback (funciona incluso abriendo el archivo como content://).
    try {
        const v = getNoSleepVideoEl();
        await v.play();
        wakeLockMode = 'video';
        return true;
    } catch (e) {
        wakeLockMode = null;
        return false;
    }
}

function releaseWakeLockNow() {
    if (wakeLock) {
        try { wakeLock.release(); } catch (e) {}
        wakeLock = null;
    }
    if (noSleepVideoEl) {
        try { noSleepVideoEl.pause(); } catch (e) {}
    }
    wakeLockMode = null;
}

function updateWakeLockBtn() {
    const btn = document.getElementById('wakeLockBtn');
    if (!btn) return;
    btn.textContent = wakeLockEnabled ? '🔆' : '🔅';
    btn.classList.toggle('active', wakeLockEnabled);
    btn.title = wakeLockEnabled
        ? (wakeLockMode === 'video' ? 'Pantalla siempre encendida (modo compatibilidad)' : 'Pantalla siempre encendida (activo)')
        : 'Evitar que la pantalla se bloquee';
}

async function toggleWakeLock() {
    const turningOn = !wakeLockEnabled;
    if (turningOn) {
        const ok = await requestWakeLock();
        if (!ok) {
            wakeLockEnabled = false;
            try { localStorage.setItem('wakeLockEnabled', '0'); } catch (e) {}
            updateWakeLockBtn();
            alert(!('wakeLock' in navigator)
                ? 'Este navegador no soporta mantener la pantalla encendida.'
                : 'No se pudo activar. Si abriste este archivo directo desde el celular (no desde una página web), probá tocar el botón de nuevo — si sigue sin funcionar, es una limitación de cómo Chrome carga el archivo así (content://) y necesitarías alojarlo en un servidor (https) o instalarlo como app para que funcione siempre.');
            return;
        }
        wakeLockEnabled = true;
    } else {
        releaseWakeLockNow();
        wakeLockEnabled = false;
    }
    try { localStorage.setItem('wakeLockEnabled', wakeLockEnabled ? '1' : '0'); } catch (e) {}
    updateWakeLockBtn();
}

function initWakeLock() {
    let saved = '0';
    try { saved = localStorage.getItem('wakeLockEnabled') || '0'; } catch (e) {}
    wakeLockEnabled = saved === '1';
    updateWakeLockBtn();
    if (wakeLockEnabled) {
        requestWakeLock().then(ok => {
            if (!ok) {
                wakeLockEnabled = false;
                try { localStorage.setItem('wakeLockEnabled', '0'); } catch (e) {}
            }
            updateWakeLockBtn();
        });
    }
}

